def main():
    print("🌍 [Global Places Ingestion] 21개 글로벌 도시 핵심 랜드마크 적재 시작...")
    
    db_url = os.getenv("DATABASE_URL", "postgresql://postgres:password@database:5432/traivldb")
    connection_string = db_url.replace("postgresql://", "postgresql+psycopg2://", 1)
    
    embeddings_model = HuggingFaceEmbeddings(model_name="jhgan/ko-sbert-nli")
    
    vector_db = PGVector(
        embedding_function=embeddings_model,
        collection_name="travel_places",
        connection_string=connection_string
    )
    
    docs = []
    ids = []
    for idx, p in enumerate(GLOBAL_PLACES_DATA):
        doc_id = f"global_{p['destination']}_{idx}"
        docs.append(Document(
            page_content=f"{p['name']} - {p['desc']} 카테고리: {', '.join(p['tags'])}",
            metadata={
                "place_id": doc_id,
                "name": p["name"],
                "country": p["country"],
                "destination": p["destination"],
                "lat": p["lat"],
                "lng": p["lng"],
                "tags": p["tags"],
                "duration_mins": 90
            }
        ))
        ids.append(doc_id)
        
    print(f"📦 총 {len(docs)}개 글로벌 장소 생성 완료. 벡터 DB에 Upsert 적재 중...")
    vector_db.delete(ids=ids)
    vector_db.add_documents(docs, ids=ids)
    print("✨ [완료] 방콕, 싱가포르, 타이베이, 하노이, 발리, 런던, 암스테르담, 취리히, 뉴욕, LA, 하와이, 시드니, 카이로, 쿠스코 전체 적재 완료!")

if __name__ == "__main__":
    main()
